// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let x, y, w, h, pad, diam;

let shadow = "#325d79";
let brown = "#f9a26c"; // langit cerah
let bg = "#9bd7d1"; //teal

function setup() {
  createCanvas(600, 600);
  noLoop();
  init();
}

function init() {
  x = 160;
  y = 120;
  w = width-2*x;
  h = height-2*y;
  pad = 15;
  diam = 100;
}

function draw() {
  background(bg);
  strokeWeight(1);
  translate(x, y);
  let off = 5;
  pushMatrix();
  translate(off, off);
  noStroke();
  frame(shadow);
  popMatrix();
  stroke(0);
  frame(bg);

  let minDrop = 5;
  let maxDrop = 35;
  let minr = 5;
  let maxr = 10;

  stroke(255);
  for (i = 1; i < 150; i++) {
    let xpos = int(random(off, w-2*pad));
    let ypos = int(random(off, h-2*pad-maxDrop));
    line(pad+xpos, pad+ypos, pad+xpos, pad+ypos+int(random(minDrop, maxDrop)));
  }
  for (i = 1; i < 30; i++) {
    var xpos = int(random(maxr, w-2*pad-maxr));
    var ypos = int(random(maxr, h-2*pad-maxr));
    let r = int(random(minr, maxr));
    ellipse(pad+xpos, pad+ypos, r, r);
  }

  stroke(0);
  fill(brown);
  triangle(w-pad, pad+1, w-pad, h-pad, pad, h-pad);

  // Sun
  fill(255, 255, 0);
  arc(w-pad, h-pad, diam, diam, PI, 3*PI/2);

  // Umbrella
  fill(0);
  let rad = 100;
  strokeWeight(3);
  line(pad, h-pad, pad, h+60);
  arc(pad, h+55, rad, rad, 0, PI);
}

function frame(c) {
  fill(c);
  beginShape();
  vertex(0, h-2*pad);
  vertex(0, 0);
  vertex(w, 0);
  vertex(w, h);
  vertex(0, h);
  vertex(0, h-pad);
  vertex(w-pad, h-pad);
  vertex(w-pad, pad);
  vertex(pad, pad);
  vertex(pad, h-2*pad);
  vertex(0, h-2*pad);
  endShape(); 
}

function mouseReleased() {
  init();
  redraw();
}

